  twniju: {
    audio: 2,
    zhuSkill: true,
    trigger: {
      global: "compare"
    },
    priority: 1,
    filter(event2, player2) {
      if (!player2.hasZhuSkill("twniju")) {
        return false;
      }
      if (event2.iwhile || event2.target && event2.compareMeanwhile) {
        return false;
      }
      const participant = [event2.player];
      if (event2.targets) {
        participant.addArray(event2.targets);
      } else {
        participant.add(event2.target);
      }
      return participant.includes(player2);
    },
    async cost(event2, trigger, player2) {
      const num = game.countPlayer((current) => current.group === "qun");
      const dialog = [
        get.prompt("twniju"),
        `<div class="text center">令一张拼点牌的点数+${num}或-${num}</div>`,
        [
          [
            ["add", "增加"],
            ["subtract", "减少"]
          ],
          "tdnodes"
        ]
      ];
      const lose_list = trigger.lose_list.slice().sort((a, b) => lib.sort.seat(a[0], b[0]));
      dialog.push(
        `<div class="text center">${lose_list.map((list) => {
          return get.translation(list[0]);
        }).join("　 / 　")}</div>`
      );
      const cards2 = lose_list.map((list) => list[1]).flat();
      dialog.push(cards2);
      const result = await player2.chooseButton({
        createDialog: dialog,
        selectButton: 2,
        filterButton: (button) => {
          const type = typeof button.link;
          if (ui.selected.buttons.length && type === typeof ui.selected.buttons[0].link) {
            return false;
          }
          return true;
        }
      }).forResult();
      if (!result.bool) {
        event2.result = result;
        return;
      }
      const { links } = result;
      if (typeof links[0] !== "string") {
        links.reverse();
      }
      const [fn, card] = links;
      const selectedPlayer = lose_list.find((item) => {
        if (Array.isArray(item[1])) {
          return item[1].includes(card);
        }
        return item[1] === card;
      })[0];
      event2.result = {
        bool: true,
        targets: [selectedPlayer],
        cost_data: { fn, card, num }
      };
    },
    async content(event2, trigger, player2) {
      const selectedPlayer = event2.targets[0];
      const { fn, card, num } = event2.cost_data;
      selectedPlayer.addTempSkill("twniju_change");
      if (!selectedPlayer.storage.twniju_change) {
        selectedPlayer.storage.twniju_change = [];
      }
      selectedPlayer.storage.twniju_change.push([fn, num, card]);
      player2.when("chooseToCompareAfter").filter((evt) => evt === trigger).step(async (event3, trigger2, player3) => {
        const num1 = trigger2.result.num1;
        const num2 = trigger2.result.num2;
        let bool = false;
        if (typeof num1 === "number" && typeof num2 === "number") {
          if (num1 === num2) {
            bool = true;
          }
        } else {
          const num1List = num1.toUniqued();
          const totalList = num1List.concat(num2).toUniqued();
          if (totalList.length < num1List.length + num2.length) {
            bool = true;
          }
        }
        if (bool) {
          await player3.draw(num);
        }
      });
    },
    subSkill: {
      change: {
        trigger: { global: "compare" },
        filter(event2, player2) {
          const storage = player2.getStorage("twniju_change");
          if (!storage.length) {
            return false;
          }
          if ((player2 !== event2.player || event2.iwhile) && player2 !== event2.target) {
            return false;
          }
          return event2.lose_list.some((list) => {
            const cards2 = Array.isArray(list[1]) ? list[1] : [list[1]];
            return list[0] === player2 && storage.some((s) => cards2.includes(s[2]));
          });
        },
        charlotte: true,
        forced: true,
        silent: true,
        async content(event2, trigger, player2) {
          const [fn, num] = player2.getStorage("twniju_change").find((s) => {
            return trigger.lose_list.some((list) => {
              const cards2 = Array.isArray(list[1]) ? list[1] : [list[1]];
              return list[0] === player2 && cards2.includes(s[2]);
            });
          });
          const numId = player2 === trigger.player ? "num1" : "num2";
          if (fn === "add") {
            trigger[numId] += num;
          } else {
            trigger[numId] -= num;
          }
          if (trigger[numId] > 13) {
            trigger[numId] = 13;
          } else if (trigger[numId] < 1) {
            trigger[numId] = 1;
          }
          game.log(player2, "的拼点牌点数", fn === "add" ? "+" : "-", num);
        }
      }
    }
  },
