            const hs = get.event().max;
            let card = { name: "sha", nature: "fire", isCard: true }, cache = ai.guessTargetPoints(target, player3, null, "10"), max = cache.max, tar = target, eff = -get.attitude(player3, target);
            if (target.hasSkill("twlvren")) {
              max += 2 * (ui.selected.targets.length + 1);
            }
            if (target.hasSkill("twchuanshu_effect")) {
              max += 3;
            }
            max = Math.min(13, max);
            cache.max = max;
            for (const cur of ui.selected.targets) {
              const temp = ai.guessTargetPoints(cur, player3);
              if (temp.max > max) {
                max = temp.max;
                tar = cur;
              }
            }
            if (hs > max) {
              return (player3.canUse(card, target, false) ? get.effect(target, card, player3, player3) : 0) + eff - 5 + ui.selected.targets.reduce((acc, p) => {
                return acc + (player3.canUse(card, p, false) ? get.effect(p, card, player3, player3) : 0) - get.attitude(player3, p);
              }, 0);
            }
            return (tar.canUse(card, player3, false) ? get.effect(player3, card, tar, player3) : 0) + eff - 5 + ui.selected.targets.reduce((acc, p) => {
              return acc + (tar.canUse(card, p, false) ? get.effect(p, card, tar, player3) : 0) - get.attitude(player3, p);
            }, 0);
